// Definition for a Huffman tree node.
class Node {
    int freq;
    char data;        // meaningful only at leaves
    Node left;
    Node right;
}

void decode(String s, Node root) {
    StringBuilder out = new StringBuilder();
    Node node = root;
    for (int i = 0; i < s.length(); i++) {
        node = (s.charAt(i) == '0') ? node.left : node.right;  // 0=left, 1=right
        if (node.left == null && node.right == null) {          // leaf reached
            out.append(node.data);
            node = root;                                        // reset for next code
        }
    }
    System.out.println(out.toString());
}

import java.util.*;

Map<String, Character> buildCodes(Node node, String path, Map<String, Character> map) {
    if (node == null) return map;
    if (node.left == null && node.right == null) {   // leaf
        map.put(path.isEmpty() ? "0" : path, node.data);
        return map;
    }
    buildCodes(node.left, path + "0", map);
    buildCodes(node.right, path + "1", map);
    return map;
}

void decode(String s, Node root) {
    Map<String, Character> codes = buildCodes(root, "", new HashMap<>());
    StringBuilder out = new StringBuilder();
    StringBuilder buf = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        buf.append(s.charAt(i));
        Character c = codes.get(buf.toString());
        if (c != null) {                              // prefix-free → first match is final
            out.append(c);
            buf.setLength(0);
        }
    }
    System.out.println(out.toString());
}

